code='''def transform(grid):
    from collections import Counter, defaultdict
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    # Connect matching non-background markers in each row and column.
    for r in range(h):
        by_color = defaultdict(list)
        for c, value in enumerate(grid[r]):
            if value != bg:
                by_color[value].append(c)
        for cols in by_color.values():
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    for c in range(w):
        by_color = defaultdict(list)
        for r in range(h):
            value = grid[r][c]
            if value != bg:
                by_color[value].append(r)
        for rows in by_color.values():
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    return out
'''
